/** cached readiness */
function makeCachedReady(ping, ttlMs, now) {
  // Write your solution here
  let last = null, pings = 0;
  async function check() {
    if (last && last.ok && now() - last.at < ttlMs) return true;
    pings++;
    await ping();
    last = { ok: true, at: now() };
    return true;
  }
  return { check, pings: () => pings };
}

